local function applyCamera()
    local camera = workspace.CurrentCamera
    if not camera then
        return
    end
    if originalCameras[camera] == nil then
        originalCameras[camera] = camera.FieldOfView
    end
    camera.FieldOfView = state.customCamera and state.fieldOfView or originalCameras[camera]
end

local function applyLighting()
    if state.customLighting then
        Lighting.Brightness = state.brightness
        Lighting.ClockTime = state.clockTime
        Lighting.FogEnd = state.fogDistance
    else
        for property, value in pairs(originalLighting) do
            Lighting[property] = value
        end
    end
end

